module.exports=[[60168,a=>{var b=a.i(7997),c=a.i(30174);let d=[{id:"uxc-sparkle-button",title:"Никто не просил кнопку со звёздочкой",summary:"Автор, который пишет код с ИИ, объясняет, почему AI-панели со «звёздочкой» появляются везде. ИИ стоит встраивать в конкретный сценарий, а не в универсальную кнопку «Ask anything».",source:"UX Collective",url:"https://uxdesign.cc/nobody-asked-for-the-sparkle-button-ae54ab5065c6",publishedAt:"2026-10-25T12:33:00Z",readingTime:6,topics:["AI","UX","Product Design"],cover:"covers/uxc-sparkle.jpg",coverAlt:"Иллюстрация к статье о шаблонных AI-панелях в продуктах",language:"en"},{id:"nng-ai-in-ux",title:"AI в UX: работа быстрее, но отношение смешанное",summary:"Опрос 521 UX-специалиста: ИИ экономит время, но 59% пользуются только одобренными инструментами. Внедрение сверху и ненадёжный результат съедают выгоду — она зависит от роли и проверки.",source:"Nielsen Norman Group",url:"https://www.nngroup.com/articles/ai-in-ux-survey-26/",publishedAt:"2026-10-23T17:00:00Z",readingTime:8,topics:["AI","Research","Product Design"],cover:"covers/nng-ai-ux.jpg",coverAlt:"Обложка исследования NN/g об использовании AI в UX-работе",language:"en"},{id:"smash-accordion-icons",title:"Иконки аккордеонов: что работает лучше",summary:"Виталий Фридман сравнивает стрелки, шевроны, треугольники и каретки в аккордеонах. Каретка — самый безопасный вариант; иконка и подпись не должны вести на разные действия. С исследованиями и примерами.",source:"Smashing Magazine",url:"https://www.smashingmagazine.com/2026/10/accordion-icons-which-work-best/",publishedAt:"2026-10-23T13:00:00Z",readingTime:5,topics:["UX","UI","Research"],cover:"covers/smash-accordion.jpg",coverAlt:"Иллюстрация с вариантами иконок для раскрывающихся меню",language:"en"},{id:"uxc-atomic-design",title:"Атомарный дизайн со стороны экрана",summary:"Обычно дизайн-систему собирают снизу вверх: атомы, компоненты, страницы. Автор предлагает обратный вход — от сценария на экране к нужным компонентам, чтобы не потерять смысл интерфейса за инвентаризацией.",source:"UX Collective",url:"https://uxdesign.cc/entering-atomic-design-from-the-screen-bae744ecc288",publishedAt:"2026-10-23T11:16:00Z",readingTime:7,topics:["Design Systems","UX","UI"],cover:"covers/uxc-atomic.jpg",coverAlt:"Схема перехода от экрана к атомарным компонентам дизайн-системы",language:"en"},{id:"habr-designer-ai",title:"Умрёт ли профессия дизайнера из-за ИИ? Реальная ситуация в индустрии",summary:"Автор поговорил с дизайн-лидами Альфа-Банка, ВКонтакте, Билайна и Dodo Pizza. Массовых сокращений нет: ИИ забирает механическую работу, а найм смещается к специалистам, отвечающим за результат.",source:"Хабр",url:"https://habr.com/ru/articles/1098332/",publishedAt:"2026-10-23T09:26:47Z",readingTime:6,topics:["AI","Product Design","Research"],cover:"covers/habr-ai.jpg",coverAlt:"Обложка статьи о влиянии ИИ на профессию дизайнера",language:"ru"},{id:"figma-agent-design-system",title:"Как подключить дизайн-систему к Figma-агенту",summary:"Практическое руководство: агент получает контекст из опубликованной библиотеки, компонентов, токенов и документации. На примере чекаута показано, как он собирает карточку заказа из утверждённых компонентов.",source:"Figma Blog",url:"https://www.figma.com/blog/how-to-put-your-design-system-to-work-with-the-figma-agent/",publishedAt:"2026-10-23T02:27:00Z",readingTime:6,topics:["Design Systems","AI","Tools"],cover:"covers/figma-agent.jpg",coverAlt:"Материалы Figma о работе дизайн-системы с AI-агентом",language:"en"},{id:"vc-product-research",title:"Бизнес не бизнес, если в нём нет исследований",summary:"Алина Игнатьева объясняет, зачем бизнесу исследования и когда их запускать: падают продажи, непонятны причины, команда уверена, что «знает» клиента. Кейс личного кабинета показывает цену такой уверенности.",source:"vc.ru",url:"https://vc.ru/design/3210221-kak-ponyat-kogda-neobkhodimo-issledovanie-produkta",publishedAt:"2026-10-22T19:54:57Z",readingTime:6,topics:["Research","Product Design","UX"],cover:"covers/vc-research.jpg",coverAlt:"Обложка статьи о продуктовых исследованиях для бизнеса",language:"ru"},{id:"vc-figma-tabs",title:"Как я настроила переключение между компонентами табов в Figma",summary:"Кейс синхронизации дизайн-системы с кодом: в Figma три разных таба, в разработке — один компонент. Автор показывает, как привести свойства к общему виду и сохранить текст и состояния.",source:"vc.ru",url:"https://vc.ru/design/3210505-perekljuchenie-mezhdu-komponentami-tabov-v-figma",publishedAt:"2026-10-22T18:02:02Z",readingTime:5,topics:["Design Systems","UI","Tools"],cover:"covers/vc-tabs.jpg",coverAlt:"Скриншот компонентов табов в Figma",language:"ru"},{id:"habr-interface-redesign",title:"С чего начать редизайн большого интерфейса, который ты видишь впервые",summary:"Лена Плинер разбирает подготовку к редизайну CRM/ERP-системы: анализ модулей, сценариев и повторяющихся механик. Вместо перерисовки страниц — карта связей и таблицы, которые находят системные расхождения.",source:"Хабр",url:"https://habr.com/ru/articles/1096170/",publishedAt:"2026-10-19T09:18:08Z",readingTime:13,topics:["UX","UI","Product Design"],cover:"covers/habr-redesign.jpg",coverAlt:"Обложка статьи о подготовке к редизайну сложной системы",language:"ru"},{id:"nng-synthetic-users",title:"Синтетические пользователи против реальных: вывод тот же, вариативность ниже",summary:"NN/g задали один вопрос 604 людям и 120 синтетическим респондентам. Вывод совпал, но ответы ИИ оказались однообразнее: синтетика годится для гипотез, но не заменяет живые данные там, где важны нюансы.",source:"Nielsen Norman Group",url:"https://www.nngroup.com/articles/synthetic-users-vs-human-respondents/",publishedAt:"2026-10-16T17:00:00Z",readingTime:7,topics:["AI","Research","UX"],cover:"covers/nng-synthetic.jpg",coverAlt:"Обложка исследования о синтетических респондентах",language:"en"},{id:"skillbox-figma-specs",title:"Figma представила Specs — инструмент для работы с проектной документацией",summary:"Figma выпустила Specs — Markdown-документы рядом с макетом, связанные с элементами дизайна. Спецификации можно импортировать, комментировать и отдавать AI-агентам через MCP. Доступно в бете на платных тарифах.",source:"Skillbox Media",url:"https://skillbox.ru/media/design/figma-predstavila-specs-instrument-dlya-raboty-s-proektnoy-dokumentaciey/",publishedAt:"2026-10-16T14:03:00Z",readingTime:3,topics:["Tools","Design Systems","AI"],cover:"covers/figma-specs.jpg",coverAlt:"Новость о запуске Figma Specs для проектной документации",language:"ru"},{id:"smash-ai-adoption",title:"Ваша организация неправильно внедряет ИИ?",summary:"Пол Боуг возвращается к книге Digital Adaptation, чтобы показать: внедрение ИИ снова сводят к закупке инструментов, забывая про процессы и людей. Выигрывают те, кто меняет способ работы, а не только стек.",source:"Smashing Magazine",url:"https://www.smashingmagazine.com/2026/10/is-your-organization-messing-up-ai-adoption/",publishedAt:"2026-10-16T10:00:00Z",readingTime:11,topics:["AI","Product Design","UX"],cover:"covers/smash-ai-adoption.jpg",coverAlt:"Иллюстрация к статье о внедрении ИИ в организациях",language:"en"},{id:"maze-market-research",title:"ИИ в маркетинговых исследованиях: что нового в Maze",summary:"Maze описывает «исследовательское сжатие»: у ресерчеров в среднем 4,5 новые зоны ответственности, ожидания по скорости выросли у 78%, а бюджеты — только у 30%. Ответ — AI-инструменты внутри процесса.",source:"Maze Blog",url:"https://maze.co/blog/ai-for-market-research/",publishedAt:"2026-10-08T06:28:33Z",readingTime:6,topics:["AI","Research","Product Design"],cover:"covers/maze-market.jpg",coverAlt:"Обложка материала Maze об AI для маркетинговых исследований",language:"en"},{id:"maze-mcp",title:"Maze MCP: как связать исследование с рабочими инструментами",summary:"Практические сценарии Maze MCP: вытащить боли из всего исследования, сравнить варианты дизайна, проверить качество данных и перейти от вывода к цитатам участников. Помогает пройти момент «подключили — что дальше».",source:"Maze Blog",url:"https://maze.co/blog/maze-mcp-best-practices/",publishedAt:"2026-08-18T20:49:00Z",readingTime:8,topics:["Tools","Research","AI"],cover:"covers/maze-mcp.jpg",coverAlt:"Обложка статьи о сценариях использования Maze MCP",language:"en"},{id:"figma-ai-report",title:"AI-отчёт Figma 2026: ИИ меняет не работу, а совместную работу",summary:"Отчёт опирается на три года данных: 8 403 ответа и 639 интервью из десяти стран. Впервые ИИ заметно меняет командные процессы: 41% респондентов говорят об этом против 7% два года назад.",source:"Figma Blog",url:"https://www.figma.com/blog/2026-ai-report/",publishedAt:"2026-06-24T12:45:00Z",readingTime:6,topics:["AI","Research","Product Design"],cover:"covers/figma-ai-report.jpg",coverAlt:"Обложка AI-отчёта Figma за 2026 год",language:"en"},{id:"bbe-digital-fatigue",title:"Как снизить цифровую усталость в интерфейсах",summary:"Татьяна Андронова разбирает цифровую усталость: когда все элементы одинаково важны, пользователь уходит из-за утомительного пути, а не плохого продукта. Практика — иерархия, ритм и снижение визуального шума.",source:"Bang Bang Education",url:"https://bangbangeducation.ru/point/avtorskiie-kolonki/kak-snizit-tsifrovuiu-ustalost-v-intierfieisakh/",publishedAt:"2026-06-18T15:26:16Z",readingTime:8,topics:["UX","UI","Product Design"],cover:"covers/bbe-fatigue.jpg",coverAlt:"Иллюстрация к колонке о цифровой усталости в интерфейсах",language:"ru"},{id:"uxj-design-systems",title:"Дизайн-системы: 11 примеров в Figma и GitHub на 2026 год",summary:"Подборка дизайн-систем VK, Сбера, Яндекса, Росатома, Apple, Google, IBM и Shopify с исходниками в Figma и GitHub. Автор объясняет, зачем система нужна команде и как она помогает масштабировать дизайн.",source:"UX Journal",url:"https://ux-journal.ru/design-systems.html",publishedAt:"2024-04-11T15:54:00Z",readingTime:12,topics:["Design Systems","Tools","UI"],cover:"covers/uxj-design-systems.jpg",coverAlt:"Коллаж с примерами дизайн-систем из статьи UX Journal",language:"ru"},{id:"uxj-ethnography",title:"UX-исследования: первая практика в этнографии",summary:"Перевод Эрики Холл о minimum viable ethnography: как за 15 минут наблюдения и один точный вопрос получить контекст, которого не дают метрики и интервью в переговорке. Хороший первый шаг исследования.",source:"UX Journal",url:"https://ux-journal.ru/minimum-viable-ethnography.html",publishedAt:"2024-04-11T12:21:00Z",readingTime:9,topics:["Research","UX","Product Design"],cover:"covers/uxj-ethnography.jpg",coverAlt:"Обложка статьи о методике минимальной этнографии",language:"ru"}];async function e(){return[...d].sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt))}async function f(){let a=await e();return(0,b.jsx)(c.DigestExperience,{articles:a})}a.s(["default",0,f],60168)},77990,a=>{let b=(0,a.i(11857).registerClientReference)(function(){throw Error("Attempted to call DigestExperience() from the server but DigestExperience is on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.")},"[project]/src/components/digest-experience.tsx","DigestExperience");a.s(["DigestExperience",0,b])},30174,a=>{var b=a.i(77990);a.n(b)}],28004,function(a){a.n(a.i(60168))}];

